package com.mybank.pbac.controller;
import com.mybank.pbac.dto.PolicyRequest; import com.mybank.pbac.model.*; import com.mybank.pbac.service.PolicyService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/policies") public class PolicyController{private final PolicyService s;public PolicyController(PolicyService s){this.s=s;}@GetMapping public List<Policy> all(@RequestParam(required=false)Long industryId,@RequestParam(required=false)GuardrailType guardrail,@RequestParam(required=false)Boolean enabled,@RequestParam(required=false)String q){return s.all(industryId,guardrail,enabled,q);}@GetMapping("/{id}")public Policy one(@PathVariable Long id){return s.one(id);}@PostMapping public Policy add(@Valid @RequestBody PolicyRequest r){return s.save(null,r);}@PutMapping("/{id}")public Policy edit(@PathVariable Long id,@Valid @RequestBody PolicyRequest r){return s.save(id,r);}@DeleteMapping("/{id}")public void del(@PathVariable Long id){s.delete(id);}}
